import openpyxl, openpyxl.worksheet.formula as af
gold = openpyxl.load_workbook('/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/3_59643_answer_template_6489_golden.xlsx', data_only=False)
