wg=gold['Data']; wi=inp['Data']
def norm(v):
    if v is None: return None
    if isinstance(v,str) and v.startswith('='): return ('F', v)
    if isinstance(v, af.ArrayFormula): return ('AF', v.text)
    return ('V', v)
# compare full used range max 5895 x 39
diffs=[]
for r in range(1, max(wg.max_row, wi.max_row)+1):
    for c in range(1, max(wg.max_column, wi.max_column)+1):
        a=norm(wg.cell(row=r,column=c).value)
        b=norm(wi.cell(row=r,column=c).value)
        if a!=b:
            diffs.append((r,c,openpyxl.utils.get_column_letter(c),repr(wi.cell(row=r,column=c).value),repr(wg.cell(row=r,column=c).value)))
print('total diffs', len(diffs))
from collections import Counter
print(Counter(c for _,_,c,_,_ in diffs))
# style diffs full
sdiffs=[]
for r in range(1, max(wg.max_row, wi.max_row)+1):
    for c in range(1, max(wg.max_column, wi.max_column)+1):
        if wg.cell(row=r,column=c).number_format != wi.cell(row=r,column=c).number_format:
            sdiffs.append((r,c))
print('style diffs', len(sdiffs))
